// src/config.rs
#[derive(Deserialize)]
#[serde(rename_all = "camelCase")]
pub struct Config {
    pub name: String,
    pub port: u16,
    pub admin_email: String,
}

/// Resolves the default config path: the crate-root `config.json`
/// (pinned at compile time via `CARGO_MANIFEST_DIR`), overridable at
/// runtime by the `CONFIG_PATH` environment variable.

// src/config.rs
pub fn default_config_path() -> std::path::PathBuf {
    match env::var("CONFIG_PATH") {
        Ok(override_path) => std::path::PathBuf::from(override_path),
        Err(_) => Path::new(env!("CARGO_MANIFEST_DIR")).join("config.json"),
    }
}

/// Reads the JSON file at `path` and deserializes it into a `Config`.
/// Both I/O failures and JSON parse failures surface as
/// `Box<dyn std::error::Error>`.

// src/config.rs
pub fn load_config(path: &Path) -> Result<Config, Box<dyn std::error::Error>> {
    let raw = fs::read_to_string(path)?;
    let config = serde_json::from_str(&raw)?;
    Ok(config)
}

